mapper.insert:
INSERT INTO tb_chat_session (
    chat_session_no, anonymous_id, user_no, scenario_no, version_no, current_node_no,
    session_type, state, expires_at, ip_hash, user_agent_hash
)
VALUES (
    #{chatSessionNo}::uuid, #{anonymousId}::uuid, #{userNo}, #{scenarioNo}, #{versionNo}, #{currentNodeNo},
    COALESCE(#{sessionType}, 'SCENARIO'), #{state}, #{expiresAt}, #{ipHash}, #{userAgentHash}
)

INSERT INTO tb_chat_session_event (
    session_no, event_type, trigger_message_no, detail
)
VALUES (
    #{sessionId}::uuid, 'NODE_BACK', #{triggerMessageNo}, CAST(#{detail} AS jsonb)
)

mapper.delete:
DELETE FROM tb_chat_session
WHERE chat_session_no IN (
    SELECT chat_session_no
    FROM tb_chat_session
    WHERE frst_reg_dt < #{cutoff}
    ORDER BY frst_reg_dt, chat_session_no
    LIMIT #{limit}
)
